import sys, os, json, random
sys.path.insert(0, os.environ["REPO_ROOT"])
from analysis.complexity_model.sampler import write_samples
from analysis.complexity_model.priors import PROBES, BASE_CAPABILITY
from analysis.complexity_model.canonical import convert_tool
from analysis.complexity_model.features import extract_step_features
from analysis.complexity_model.elicit import self_pair_id
from pre_processing.trajectory_analyzer import analyze

samples_path, responses_path, n = sys.argv[1], sys.argv[2], int(sys.argv[3])
write_samples(os.path.join(os.environ["REPO_ROOT"], "data/trajectories_v1_01.jsonl"), n, samples_path, seed=7)
rows = [json.loads(l) for l in open(samples_path)]

def dummy(schema):
    t = schema.get("type")
    return {"string":"x","integer":1,"number":1,"boolean":True,"array":[],"object":{}}.get(t,"x")

def resp(model, feats, rng, tds):
    contested = min(1.0, feats["recent_error_rate"]*0.7 + (feats["max_repeat_run"]-1)*0.15)
    if rng.random() < 0.05 + 0.4*contested*(1-BASE_CAPABILITY[model]):
        return {"output":[{"type":"message","content":[{"type":"output_text","text":"done"}]}]}
    pool = [x for x in tds if x in ("bash","file_read","file_edit","shell_command","apply_patch")] or list(tds)
    k = 1 if rng.random() > contested or len(pool)<2 else 2
    names = rng.sample(pool,k)
    return {"output":[{"type":"function_call","name":nm,
             "arguments": json.dumps({k2: dummy((tds[nm].parameters.get("properties") or {}).get(k2,{}))
                                      for k2 in (tds[nm].parameters.get("required") or [])})} for nm in names]}

selfpair = {r["step_id"] for r in rows if r["served_model"].startswith("gpt")}
with open(responses_path,"w") as out:
    for r in rows:
        tds = {t["name"]: convert_tool(t) for t in r["tools"]}
        traj = analyze({"model": r["served_model"], "input": r["prefix_items"], "tools": r["tools"]}, id=r["trajectory_id"])
        feats = extract_step_features(traj)
        rng = random.Random(hash(r["step_id"]) & 0xffffffff)
        for m in PROBES:
            out.write(json.dumps({"model":m,"step_id":r["step_id"],"status":"ok","raw":resp(m,feats,rng,tds)})+"\n")
        if r["step_id"] in selfpair:
            for m in PROBES:
                out.write(json.dumps({"model":self_pair_id(m),"step_id":r["step_id"],"status":"ok","raw":resp(m,feats,rng,tds)})+"\n")
print(f"{len(rows)} samples, {len(selfpair)} with self-pairs")
