import sys, json; sys.path.insert(0,'.')
from collections import Counter
from analysis.complexity_model.sampler import Sample

samples=[Sample(**json.loads(l)) for l in open('analysis/complexity_model/store/samples.jsonl')]
print(f"{len(samples)} samples\n")

# What does the item immediately before the cut look like? That's the decision context.
last_kind=Counter(); out_shape=Counter(); tool_last=Counter()
for s in samples:
    if not s.prefix_items: continue
    it=s.prefix_items[-1]; t=it.get('type') or 'message'
    last_kind[f"{t}/{it.get('role')}" if t=='message' else t]+=1
    if t in ('function_call_output','custom_tool_call_output'):
        o=str(it.get('output') or '')
        try:
            j=json.loads(o)
            keys=tuple(sorted(j)) if isinstance(j,dict) else ('<non-dict>',)
            out_shape[keys]+=1
        except Exception:
            out_shape[('<not json>',)]+=1
    # what tool was last invoked anywhere in prefix
for s in samples:
    for it in reversed(s.prefix_items):
        if (it.get('type') or '') in ('function_call','custom_tool_call'):
            tool_last[it.get('name')]+=1; break

print("item immediately before the cut:")
for k,v in last_kind.most_common(8): print(f"   {v:>5}  {k}")
print("\nstructure of the last tool output (JSON keys):")
for k,v in out_shape.most_common(8): print(f"   {v:>5}  {k}")
print("\nlast tool invoked before the cut (RAW names - dialect-correlated, do not use directly):")
for k,v in tool_last.most_common(12): print(f"   {v:>5}  {k}")
